k = int(input())
for i in range(k):
    a = int(input())
    b = int(input())
    c = 180 - a - b
    if c <= 0:
        print(f"{a}, {b}: no triangle")
    elif a == 90 or b == 90 or c == 90:
        print(f"{a}, {b}: third angle {c}, right")
    elif a > 90 or b > 90 or c > 90:
        print(f"{a}, {b}: third angle {c}, obtuse")
    else:
        print(f"{a}, {b}: third angle {c}, acute")

