def name_test(parts):
    print(f"Known in order: {parts}")
    if parts == "SSS":
        print("  three sides: SSS")
    elif parts == "SAS":
        print("  the angle is between the two sides: SAS")
    elif parts == "ASA":
        print("  the side is between the two angles: ASA")
    elif parts == "AAS" or parts == "SAA":
        print("  the side is not between the angles: AAS")
        print("  the angle sum gives the third angle, so it is ASA too")
    elif parts == "SSA" or parts == "ASS":
        print("  the angle is not between the sides: not a test")
        print("  the free side can swing to two places")
    else:
        print("  only angles: not a test, the sizes can differ")

name_test("SSS")
name_test("SAS")
name_test("ASA")
name_test("SAA")
name_test("SSA")
name_test("AAA")

